import frida
import sys
import json
import time

sys.stdout.reconfigure(encoding="utf-8")

STABILIZE_LUA = '-- Last Z live graphics remediation patch (xLua)\n-- Scope:\n--   1. Hardened IsNull(o) & table.count(t) xLua/C# fallbacks\n--   2. Camera Depth Buffer Clamp (Near=20.0, Far=12000.0 -> 600:1 Ratio)\n--   3. QualitySettings + URP Shadow Normalization (Offset=0.8, Dist=150.0, Cascades=2)\n--   4. WorldPointAdjuster & LOD Hysteresis Padding (Anti-Thrashing 3D <-> 2D)\n\n-- - Hardened xLua compatibility helpers (IsNull & table.count)\nlocal function IsNull(o)\n    if o == nil then return true end\n    if type(o) == "userdata" then\n        local ok, res = pcall(function() return o:Equals(nil) end)\n        if ok then return res end\n    end\n    return false\nend\n_G.IsNull = _G.IsNull or IsNull\n\nlocal function SafeTableCount(t)\n    if t == nil then return 0 end\n    if type(t) == "table" then\n        local n = 0\n        for _ in pairs(t) do n = n + 1 end\n        return n\n    end\n    if type(t) == "userdata" then\n        local okC, c = pcall(function() return t.Count end)\n        if okC and type(c) == "number" then return c end\n        local okL, l = pcall(function() return t.Length end)\n        if okL and type(l) == "number" then return l end\n    end\n    return 0\nend\n\nif type(table) == "table" and type(table.count) ~= "function" then\n    table.count = SafeTableCount\nend\n\n-- - Main live remediation entrypoint\nlocal function ApplyLastZLiveRemediation()\n    local logOut = {}\n    local function log(msg) table.insert(logOut, msg) end\n\n    local app = CS.UnityEngine.Application\n    local qs = CS.UnityEngine.QualitySettings\n    local gs = CS.UnityEngine.Rendering and CS.UnityEngine.Rendering.GraphicsSettings\n    local ws = SceneManager and SceneManager.World\n    local wpm = DataCenter and DataCenter.WorldPointManager\n\n    local flags = CS.System.Reflection.BindingFlags\n    local toInt = CS.System.Convert.ToInt32\n    local allFlags = toInt(flags.Public) + toInt(flags.NonPublic) + toInt(flags.Instance)\n\n    -- - Camera depth precision clamp (Near=20.0, Far=12000.0 -> 600:1 Ratio)\n    local TARGET_NEAR = 20.0\n    local TARGET_FAR  = 12000.0\n\n    -- Neutralize any rogue 5.0s TimerManager heartbeat resetting Near=3.0 / Far=35000.0\n    local tm = TimerManager and TimerManager:GetInstance()\n    if tm then\n        if tm.__update_timer then\n            for timerObj, _ in pairs(tm.__update_timer) do\n                if type(timerObj) == "table" and timerObj.one_shot == true and timerObj.obj_not_nil == false and timerObj.delay == 5.0 then\n                    timerObj.over = true\n                    timerObj.target_func = function() end\n                    tm.__update_timer[timerObj] = nil\n                end\n            end\n        end\n        if not tm._safeDelayInvokeWrapped then\n            tm._safeDelayInvokeWrapped = true\n            local origDelayInvoke = tm.DelayInvoke\n            tm.DelayInvoke = function(self, func, delay, ...)\n                if delay == 5.0 and type(func) == "function" and func ~= _G._cleanHeartbeatFunc then\n                    local dinfo = debug and debug.getinfo and debug.getinfo(func, "S")\n                    if dinfo and string.find(tostring(dinfo.short_src), "%[string") then\n                        return -- Block legacy 35000/3.0 heartbeat loop from re-arming\n                    end\n                end\n                return origDelayInvoke(self, func, delay, ...)\n            end\n        end\n    end\n\n    local clampedCams = 0\n    local allCams = CS.UnityEngine.Camera.allCameras\n    if allCams then\n        for i = 0, allCams.Length - 1 do\n            local cam = allCams[i]\n            if not IsNull(cam) then\n                if cam.orthographic then\n                    -- Keep orthographic UI cameras (UICamera) from clipping UI layers\n                    if cam.nearClipPlane > 0 then\n                        cam.nearClipPlane = -100.0\n                    end\n                else\n                    cam.nearClipPlane = TARGET_NEAR\n                    cam.farClipPlane  = TARGET_FAR\n                    clampedCams = clampedCams + 1\n                end\n            end\n        end\n    end\n\n    local mainCam = CS.UnityEngine.Camera.main\n    if not IsNull(mainCam) and not mainCam.orthographic then\n        mainCam.nearClipPlane = TARGET_NEAR\n        mainCam.farClipPlane  = TARGET_FAR\n    end\n\n    if ws and ws.Camera then\n        ws.Camera.ReCalcFarPlane = function(self, camDist)\n            if not IsNull(self.camera) then\n                self.camera.nearClipPlane = TARGET_NEAR\n                self.camera.farClipPlane  = TARGET_FAR\n            end\n        end\n        if not IsNull(ws.Camera.camera) then\n            ws.Camera.camera.nearClipPlane = TARGET_NEAR\n            ws.Camera.camera.farClipPlane  = TARGET_FAR\n        end\n    end\n    log(string.format("Cameras clamped=%d (Near=%.1f, Far=%.1f, Ratio=600:1)", clampedCams, TARGET_NEAR, TARGET_FAR))\n\n    -- - Quality settings & URP shadow pipeline normalization\n    if qs then\n        qs.shadowNearPlaneOffset = 0.8\n        qs.shadowDistance        = 150.0\n        qs.shadowCascades        = 2\n    end\n\n    -- Synchronize UniversalRenderPipelineAsset_High so URP honors Distance=150 & Cascades=2\n    if gs then\n        local rp = gs.currentRenderPipeline or gs.renderPipelineAsset\n        if not IsNull(rp) then\n            rp.shadowDistance     = 150.0\n            rp.shadowCascadeCount = 2\n            rp.shadowDepthBias    = 1.2\n            rp.shadowNormalBias   = 1.2\n\n            local t = rp:GetType()\n            local fRes = t:GetField("m_MainLightShadowmapResolution", allFlags)\n            if fRes then\n                local v2048 = CS.System.Enum.ToObject(fRes.FieldType, toInt(2048))\n                fRes:SetValue(rp, v2048)\n            end\n        end\n    end\n    log("Shadows normalized (NearOffset=0.8, Dist=150.0, Cascades=2)")\n\n    -- - WorldPointAdjuster & LOD hysteresis padding (3D mesh <-> 2D icon)\n    -- Hysteresis configuration:\n    --   * 3D Models + Near Labels stay visible in LOD 1..2 (and hold through LOD 3\n    --     when zooming OUT from near view until LOD >= 4 is crossed, or after a\n    --     0.35s stabilization window).\n    --   * 2D Far Icons + Far Labels stay visible in LOD 3..12 (and hold when zooming\n    --     IN from far view until LOD <= 2 is stably reached).\n    local HYSTERESIS_COOLDOWN = 0.35 -- seconds minimum hold before flipping 3D <-> 2D band\n\n    local function ConfigureAdjusterWithHysteresis(adj)\n        if IsNull(adj) then return false end\n        local f = adj:GetType():GetField("settings", allFlags)\n        local arr = f and f:GetValue(adj)\n        if not arr or arr.Length == 0 then return false end\n\n        local settingType = arr:GetType():GetElementType()\n        local tF = settingType:GetField("targets", allFlags)\n        local lF = settingType:GetField("showLods", allFlags)\n\n        for i = 0, arr.Length - 1 do\n            local s = arr[i]\n            local targets = tF and tF:GetValue(s)\n            local isModel = false\n            local isFarIcon = false\n            local isNearLabel = false\n            local isFarLabel = false\n\n            if targets and targets.Length > 0 then\n                for t = 0, targets.Length - 1 do\n                    local tObj = targets[t]\n                    local tname = (not IsNull(tObj) and tObj.name) or ""\n                    if tname == "ModelGo" or tname == "Model" or tname == "ModelInstance" then\n                        isModel = true\n                    elseif tname == "Icon" or tname == "IconHouse" or tname == "IconNormal" or tname == "FarIcon" or tname == "lodSetObj" then\n                        isFarIcon = true\n                    elseif string.find(tname, "Near") or string.find(tname, "ModelHead") then\n                        isNearLabel = true\n                    elseif string.find(tname, "Far") or string.find(tname, "IconHead") then\n                        isFarLabel = true\n                    elseif tname == "NameLabel" or tname == "LevelLabel" then\n                        if i < 3 then\n                            isNearLabel = true\n                        else\n                            isFarLabel = true\n                        end\n                    end\n                end\n            end\n\n            local llist = lF and lF:GetValue(s)\n            if llist then\n                llist:Clear()\n                if isModel or isNearLabel then\n                    -- 3D Mesh & Near Labels strictly assigned to Near Band (LOD 1..2)\n                    llist:Add(toInt(1))\n                    llist:Add(toInt(2))\n                elseif isFarIcon or isFarLabel then\n                    -- 2D Far Icons & Far Labels strictly assigned to Far Band (LOD 3..12)\n                    for l = 3, 12 do\n                        llist:Add(toInt(l))\n                    end\n                else\n                    if arr.Length >= 4 and i < 3 then\n                        llist:Add(toInt(1))\n                        llist:Add(toInt(2))\n                    else\n                        for l = 3, 12 do\n                            llist:Add(toInt(l))\n                        end\n                    end\n                end\n            end\n        end\n        return true\n    end\n\n    -- Compute hysteresis-stabilized LOD level for 3D <-> 2D transitions:\n    -- Prevents rapid toggling when camera sits on the LOD 2 <-> LOD 3 boundary.\n    _G._lastStableBand = _G._lastStableBand or "NEAR" -- "NEAR" (<=2) or "FAR" (>=3)\n    _G._lastBandSwitchTime = _G._lastBandSwitchTime or 0\n\n    local function GetHysteresisLod(rawLod)\n        local now = CS.UnityEngine.Time.unscaledTime\n        local curBand = _G._lastStableBand\n\n        if curBand == "NEAR" then\n            -- Hysteresis padding when zooming out:\n            -- Require either LOD >= 4 immediately, or LOD == 3 held past cooldown\n            if rawLod >= 4 or (rawLod == 3 and (now - _G._lastBandSwitchTime) >= HYSTERESIS_COOLDOWN) then\n                _G._lastStableBand = "FAR"\n                _G._lastBandSwitchTime = now\n                return math.max(3, rawLod)\n            else\n                return math.min(2, rawLod) -- Hold in NEAR band (LOD 2) to prevent boundary flicker\n            end\n        else\n            -- Hysteresis padding when zooming in:\n            -- Require either LOD == 1 immediately, or LOD == 2 held past cooldown\n            if rawLod <= 1 or (rawLod == 2 and (now - _G._lastBandSwitchTime) >= HYSTERESIS_COOLDOWN) then\n                _G._lastStableBand = "NEAR"\n                _G._lastBandSwitchTime = now\n                return math.min(2, rawLod)\n            else\n                return math.max(3, rawLod) -- Hold in FAR band (LOD 3) to prevent boundary flicker\n            end\n        end\n    end\n\n    local function ApplySafeLodToAdjuster(adj, rawLod)\n        if IsNull(adj) then return end\n        local stableLod = GetHysteresisLod(rawLod or (wpm and wpm.lodLv) or 1)\n        adj:UpdateLod(stableLod)\n    end\n\n    -- Hook WorldPointObject.SetAutoAdjustLod & OnLodChanged for future spawns\n    if WorldPointObject and not WorldPointObject.__hysteresisPatched then\n        WorldPointObject.__hysteresisPatched = true\n        local origSetAutoAdjustLod = WorldPointObject.SetAutoAdjustLod\n        WorldPointObject.SetAutoAdjustLod = function(self, ...)\n            if origSetAutoAdjustLod then origSetAutoAdjustLod(self, ...) end\n            if not IsNull(self.adjuster) then\n                ConfigureAdjusterWithHysteresis(self.adjuster)\n                ApplySafeLodToAdjuster(self.adjuster, wpm and wpm.lodLv or 1)\n            end\n        end\n    end\n\n    -- Hook WorldInstancedRepresentation & WorldBuildObjectInstancedLod with hysteresis band\n    local ok_wir, wir = pcall(require, "SlgEngine.DataCenter.WorldPointManager.WorldInstancedRepresentation")\n    if ok_wir and wir then\n        wir._ApplyInstancedLodState = function(self, info, forceAll)\n            local stableLod = GetHysteresisLod(self.lodLv or (wpm and wpm.lodLv) or 1)\n            if stableLod <= 2 then\n                self:RefreshInstancedModel(info, forceAll)\n                if self.DestroyInstancedFarIcon then self:DestroyInstancedFarIcon() end\n            else\n                self:RemoveInstancedModel()\n                self:RefreshInstancedFarIcon(info, forceAll)\n            end\n            self:RefreshInstancedLabel(info)\n        end\n    end\n\n    local ok_wboil, wboil = pcall(require, "SlgEngine.DataCenter.WorldPointManager.WorldBuildObjectInstancedLod")\n    if ok_wboil and wboil then\n        wboil.OnLodChanged = function(self, lod)\n            local stableLod = GetHysteresisLod(lod or 1)\n            if self.lodLv == stableLod then return end\n            local oldLod = self.lodLv or 0\n            self.lodLv = stableLod\n            local oldNear = oldLod <= 2\n            local newNear = stableLod <= 2\n            if oldNear ~= newNear then\n                local info = wpm and wpm:GetPointInfo(self.pointIndex)\n                if info ~= nil then self:_RefreshData(info) end\n                if newNear then\n                    if self.DestroyFarIcon then self:DestroyFarIcon() end\n                    if info then\n                        self:CreateModelInstance(info)\n                        self:CreateLabel(info)\n                    end\n                else\n                    if self.DestroyModelInstance then self:DestroyModelInstance() end\n                    if info then\n                        self:CreateFarIcon(info)\n                        self:CreateLabel(info)\n                    end\n                end\n            end\n            self:_OnLodSwitched()\n            self:UpdateTargetAnchor()\n        end\n    end\n\n    -- Add Schmitt-trigger spatial hysteresis (Enter=52 tiles, Exit=60 tiles) to 3D Proximity Gate\n    local outPos  = CS.UnityEngine.Vector3(-10000, 0, -10000)\n    local zeroPos = CS.UnityEngine.Vector3.zero\n    local ENTER_DIST = 52 -- Show 3D model when within 52 tiles\n    local EXIT_DIST  = 60 -- Hide 3D model only when beyond 60 tiles (8-tile hysteresis deadband)\n\n    local function RunHysteresisProximityGate()\n        if not wpm then return end\n        local objMap = wpm.allObj or wpm.pointList\n        if not objMap then return end\n\n        local camX = (wpm.reqPos and wpm.reqPos.x) or 600\n        local camY = (wpm.reqPos and wpm.reqPos.y) or 600\n        local stableLod = GetHysteresisLod(wpm.lodLv or 1)\n\n        for _, obj in pairs(objMap) do\n            local pType = obj.pointType or (obj.GetPointType and obj:GetPointType())\n            if (pType == 6 or pType == 4 or pType == 11 or pType == 15) and not IsNull(obj.gameObject) then\n                local px = obj._cachedTileX\n                local py = obj._cachedTileY\n                if not px or not py then\n                    px, py = SceneUtils.IndexToTileXY(obj.pointIndex)\n                    obj._cachedTileX = px\n                    obj._cachedTileY = py\n                end\n\n                local dx = math.abs(px - camX)\n                local dy = math.abs(py - camY)\n\n                local modelT = obj._cachedModelT\n                if IsNull(modelT) then\n                    modelT = obj.gameObject.transform:Find("ModelGo") or obj.gameObject.transform:Find("Model")\n                    obj._cachedModelT = modelT\n                end\n\n                if not IsNull(modelT) then\n                    local isCurrentlyCulled = (modelT.localPosition.x < -1000)\n                    local shouldShow3D = false\n\n                    if stableLod <= 2 then\n                        if isCurrentlyCulled then\n                            shouldShow3D = (dx <= ENTER_DIST and dy <= ENTER_DIST)\n                        else\n                            shouldShow3D = (dx <= EXIT_DIST and dy <= EXIT_DIST)\n                        end\n                    end\n\n                    if shouldShow3D and isCurrentlyCulled then\n                        modelT.localPosition = zeroPos\n                    elseif (not shouldShow3D) and (not isCurrentlyCulled) then\n                        modelT.localPosition = outPos\n                    end\n                end\n            end\n        end\n    end\n\n    if ws and ws.Camera then\n        local afterTbl = ws.Camera.AfterUpdate or ws.Camera.AfterUpdateAction\n        if type(afterTbl) == "table" then\n            afterTbl["Proximity3DGate"] = RunHysteresisProximityGate\n        end\n    end\n\n    -- Apply hysteresis adjuster settings to all currently active world objects\n    local adjustedCount = 0\n    local totalActivePoints = 0\n    if wpm then\n        local activeMap = wpm.allObj or wpm.pointList\n        totalActivePoints = SafeTableCount(activeMap)\n        if activeMap then\n            local curLod = wpm.lodLv or 1\n            for _, pt in pairs(activeMap) do\n                if pt and not IsNull(pt.adjuster) then\n                    if ConfigureAdjusterWithHysteresis(pt.adjuster) then\n                        ApplySafeLodToAdjuster(pt.adjuster, curLod)\n                        adjustedCount = adjustedCount + 1\n                    end\n                end\n            end\n        end\n        RunHysteresisProximityGate()\n    end\n\n    log(string.format("LOD Hysteresis active (Points=%d, AdjustersPatched=%d, Cooldown=%.2fs, SpatialDeadband=%d-%d tiles)",\n        totalActivePoints, adjustedCount, HYSTERESIS_COOLDOWN, ENTER_DIST, EXIT_DIST))\n\n    return "[OK] " .. table.concat(logOut, " | ")\nend\n\nreturn ApplyLastZLiveRemediation()\n'

FRIDA_JS = r"""
const mod = Process.getModuleByName("xlua.dll");
const nf = (name, ret, args) => new NativeFunction(mod.getExportByName(name), ret, args);
const top = nf("lua_gettop", "int", ["pointer"]);
const settop = nf("lua_settop", "void", ["pointer", "int"]);
const loadstring = nf("luaL_loadstring", "int", ["pointer", "pointer"]);
const pcall = nf("lua_pcall", "int", ["pointer", "int", "int", "int"]);
const str = nf("lua_tolstring", "pointer", ["pointer", "int", "pointer"]);
const length = Memory.alloc(8);

function getString(L, index) {
    const p = str(L, index, length);
    if (p.isNull()) return "";
    const sz = Number(length.readU64());
    return sz === 0 ? "" : p.readUtf8String(sz);
}

const luaPayload = %s;

let done = false;
Interceptor.attach(mod.getExportByName("lua_pcallk"), {
    onEnter(args) {
        if (done) return;
        done = true;
        const L = args[0];
        const saved = top(L);
        try {
            const s = Memory.allocUtf8String(luaPayload);
            if (loadstring(L, s) === 0) {
                if (pcall(L, 0, 1, 0) === 0) {
                    send({ type: "result", data: getString(L, -1) });
                } else {
                    send({ type: "error", data: getString(L, -1) });
                }
            } else {
                send({ type: "error", data: "Syntax error: " + getString(L, -1) });
            }
        } catch(e) {
            send({ type: "error", data: e.toString() });
        } finally {
            settop(L, saved);
        }
    }
});
""" % json.dumps(STABILIZE_LUA)

def main():
    try:
        session = frida.attach("Survival.exe")
    except Exception as e:
        print(f"[-] Survival.exe not currently running: {e}")
        return

    res_holder = []
    script = session.create_script(FRIDA_JS)
    script.on("message", lambda m, d: res_holder.append(m.get("payload") if m.get("type") == "send" else {"type": "error", "data": str(m)}))
    script.load()

    for _ in range(30):
        if res_holder:
            break
        time.sleep(0.1)

    try:
        session.detach()
    except Exception:
        pass

    if res_holder:
        r = res_holder[0]
        if r.get("type") == "result":
            print(f"[+] Live Remediation Applied: {r.get('data')}")
        else:
            print(f"[-] Error: {r.get('data')}")
    else:
        print("[-] Timed out")

if __name__ == "__main__":
    main()
